testo:
{
 "genere": "prevedi",
 "titolo": "Ripasso: Proiettili e mira",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var direction := Vector2(1, 0)
	var speed: float = 300.0
	var velocity := direction * speed
	return velocity.x
",
   "domanda": "Quanto vale `velocity.x` alla fine?",
   "spiegazione": "`Vector2(1, 0)` moltiplicato per `300.0` produce il vettore `Vector2(300.0, 0.0)`. La componente x è quindi `300.0`."
  },
  {
   "codice": "extends RefCounted


func run():
	var shoot_cooldown: float = 0.5
	var current_cooldown: float = 0.2
	var delta: float = 0.4
	current_cooldown -= delta
	return current_cooldown <= 0.0
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "`current_cooldown` (0.2) meno `delta` (0.4) dà `-0.2`. Poiché `-0.2` è minore o uguale a `0.0`, la condizione restituisce `true` (il cooldown è esaurito e si può sparare)."
  },
  {
   "codice": "extends RefCounted


func run():
	var pos_player := Vector2(100, 100)
	var pos_mouse := Vector2(100, 0)
	var dir := pos_player.direction_to(pos_mouse)
	return dir.y < 0
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "`direction_to` calcola la direzione da `(100, 100)` a `(100, 0)`, cioè verso l'alto. In Godot l'asse Y cresce verso il basso, quindi muoversi verso l'alto genera una coordinata Y negativa (`-1.0`). La condizione `dir.y < 0` è quindi `true`."
  },
  {
   "codice": "extends RefCounted


func run():
	var lifetime: float = 2.0
	var time_passed: float = 1.5
	var delta: float = 0.6
	time_passed += delta
	return time_passed >= lifetime
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "`time_passed` parte da 1.5 e vi si aggiunge `delta` (0.6), arrivando a 2.1. Poiché 2.1 è maggiore o uguale a `lifetime` (2.0), la condizione è `true`, simulando la scadenza del proiettile."
  },
  {
   "codice": "extends RefCounted


func run():
	var current_pos := Vector2(0, 0)
	var target_pos := Vector2(3, 0)
	var distance := current_pos.distance_to(target_pos)
	return distance > 4.0
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "La distanza tra `(0, 0)` e `(3, 0)` è 3.0. Poiché 3.0 non è maggiore di 4.0, la condizione restituisce `false`."
  }
 ]
}
